#include "longhorn.h"
static void populate_files(GtkListBox*list,const char*path){GDir*d=g_dir_open(path,0,NULL);if(!d)return;const char*n;while((n=g_dir_read_name(d))){if(n[0]=='.')continue;char*full=g_build_filename(path,n,NULL);GFile*f=g_file_new_for_path(full);GFileInfo*i=g_file_query_info(f,G_FILE_ATTRIBUTE_STANDARD_TYPE,G_FILE_QUERY_INFO_NONE,NULL,NULL);const char*ic=(i&&g_file_info_get_file_type(i)==G_FILE_TYPE_DIRECTORY)?"📁":"📄";GtkWidget*r=gtk_list_box_row_new();GtkWidget*l=gtk_label_new(NULL);char*s=g_strdup_printf("%s  %s",ic,n);gtk_label_set_text(GTK_LABEL(l),s);gtk_label_set_xalign(GTK_LABEL(l),0);gtk_widget_set_margin_start(l,8);gtk_list_box_row_set_child(GTK_LIST_BOX_ROW(r),l);gtk_list_box_append(list,r);g_free(s);if(i)g_object_unref(i);g_object_unref(f);g_free(full);}g_dir_close(d);}
static void close_explorer(GtkButton*b,gpointer d){(void)b;gtk_window_destroy(GTK_WINDOW(d));}
void create_file_explorer(GtkApplication*app,const char*path){GtkWidget*w=gtk_application_window_new(app);GtkWindow*win=GTK_WINDOW(w);gtk_window_set_title(win,"My Documents");gtk_window_set_default_size(win,980,680);GtkWidget*r=gtk_box_new(GTK_ORIENTATION_VERTICAL,0);gtk_widget_add_css_class(r,"lh-explorer");gtk_window_set_child(win,r);GtkWidget*t=gtk_box_new(GTK_ORIENTATION_HORIZONTAL,4);gtk_widget_add_css_class(t,"lh-titlebar");GtkWidget*ttl=gtk_label_new("My Documents");gtk_widget_set_hexpand(ttl,TRUE);gtk_label_set_xalign(GTK_LABEL(ttl),0);gtk_box_append(GTK_BOX(t),ttl);GtkWidget*c=gtk_button_new_with_label("✕");gtk_widget_add_css_class(c,"lh-close");g_signal_connect(c,"clicked",G_CALLBACK(close_explorer),w);gtk_box_append(GTK_BOX(t),c);gtk_box_append(GTK_BOX(r),t);GtkWidget*m=gtk_box_new(GTK_ORIENTATION_HORIZONTAL,0);gtk_widget_add_css_class(m,"lh-menu");const char*menus[]={"File","Edit","View","Favorites","Tools","Help"};for(guint x=0;x<G_N_ELEMENTS(menus);x++)gtk_box_append(GTK_BOX(m),gtk_button_new_with_label(menus[x]));gtk_box_append(GTK_BOX(r),m);GtkWidget*tb=gtk_box_new(GTK_ORIENTATION_HORIZONTAL,5);gtk_widget_add_css_class(tb,"lh-toolbar");gtk_box_append(GTK_BOX(tb),gtk_button_new_with_label("←"));gtk_box_append(GTK_BOX(tb),gtk_button_new_with_label("→"));gtk_box_append(GTK_BOX(tb),gtk_button_new_with_label("↑"));GtkWidget*e=gtk_entry_new();gtk_editable_set_text(GTK_EDITABLE(e),path);gtk_widget_set_hexpand(e,TRUE);gtk_box_append(GTK_BOX(tb),e);GtkWidget*se=gtk_entry_new();gtk_entry_set_placeholder_text(GTK_ENTRY(se),"Search");gtk_widget_set_size_request(se,190,-1);gtk_box_append(GTK_BOX(tb),se);gtk_box_append(GTK_BOX(tb),gtk_button_new_with_label("▦"));gtk_box_append(GTK_BOX(r),tb);GtkWidget*p=gtk_box_new(GTK_ORIENTATION_VERTICAL,2);gtk_widget_add_css_class(p,"lh-phode");GtkWidget*pt=gtk_label_new("My Documents");gtk_label_set_xalign(GTK_LABEL(pt),0);gtk_box_append(GTK_BOX(p),pt);GtkWidget*ps=gtk_label_new("Personal files and folders   ·   all properties...");gtk_label_set_xalign(GTK_LABEL(ps),0);gtk_box_append(GTK_BOX(p),ps);gtk_box_append(GTK_BOX(r),p);GtkWidget*content=gtk_paned_new(GTK_ORIENTATION_HORIZONTAL);gtk_paned_set_position(GTK_PANED(content),220);gtk_widget_set_vexpand(content,TRUE);GtkWidget*f=gtk_box_new(GTK_ORIENTATION_VERTICAL,6);gtk_widget_add_css_class(f,"lh-filter");gtk_box_append(GTK_BOX(f),gtk_label_new("Filter by"));GtkWidget*fe=gtk_entry_new();gtk_entry_set_placeholder_text(GTK_ENTRY(fe),"Filter...");gtk_box_append(GTK_BOX(f),fe);const char*filters[]={"Recent Documents","By Modified Year","By Type","By Size"};for(guint x=0;x<G_N_ELEMENTS(filters);x++)gtk_box_append(GTK_BOX(f),gtk_button_new_with_label(filters[x]));GtkWidget*right=gtk_box_new(GTK_ORIENTATION_VERTICAL,0);GtkWidget*cols=gtk_box_new(GTK_ORIENTATION_HORIZONTAL,0);gtk_widget_add_css_class(cols,"lh-toolbar");const char*heads[]={"Name","Size","Type","Date Modified"};for(guint x=0;x<G_N_ELEMENTS(heads);x++){GtkWidget*h=gtk_button_new_with_label(heads[x]);gtk_widget_set_hexpand(h,TRUE);gtk_box_append(GTK_BOX(cols),h);}gtk_box_append(GTK_BOX(right),cols);GtkWidget*list=gtk_list_box_new();gtk_widget_set_vexpand(list,TRUE);populate_files(GTK_LIST_BOX(list),path);gtk_box_append(GTK_BOX(right),list);gtk_paned_set_start_child(GTK_PANED(content),f);gtk_paned_set_end_child(GTK_PANED(content),right);gtk_box_append(GTK_BOX(r),content);gtk_window_present(win);}
